mapper.select:
SELECT * FROM plan_template 
WHERE goal_type = #{goalType} 
AND goal_keyword = #{goalKeyword} 
AND total_days = #{totalDays}
ORDER BY quality_score DESC
LIMIT 1

SELECT * FROM plan_template 
WHERE goal_type = #{goalType} 
AND total_days BETWEEN #{totalDays} - #{daysRange} AND #{totalDays} + #{daysRange}
AND (goal_keyword LIKE CONCAT('%', #{goalKeyword}, '%') OR #{goalKeyword} LIKE CONCAT('%', goal_keyword, '%'))
ORDER BY quality_score DESC, usage_count DESC
LIMIT 5

SELECT * FROM plan_template 
ORDER BY quality_score DESC, usage_count DESC 
LIMIT #{limit}
